# Transform: 1→5, 8→1, 5→8, 6→6

output = []
for r in range(30):
    row = []
    for c in range(30):
        qr = r % 15
        qc = c % 15

        # Current quadrant (all identical)
        if qr < 4:  # Top strip
            if qc < 4:
                current = 1
            elif qc < 8:
                current = 8
            else:
                current = 6
        elif qr < 8:  # Middle strip
            if qc < 6:
                current = 8
            elif qc < 8:
                current = 5
            else:
                current = 6
        else:  # Bottom strip
            current = 6

        # Apply transformation
        if current == 1:
            color = 5
        elif current == 5:
            color = 8
        elif current == 8:
            color = 1
        else:
            color = 6

        row.append(color)
    output.append(row)

# Submit
{"action": "submit", "grid": output}

